mapper.select:
select ruser.USER_ID, ruser.COMPANY_ID, ruser.USERNAME, ruser.NICKNAME, ruser.PHONE, ruser.EMAIL, ruser.CEEA_EMP_NO, ruser.CEEA_COMPANY, ruser.CEEA_COMPANY_DESCR, ruser.CEEA_DEPTID, ruser.DEPARTMENT, ruser.CEEA_JOBCODE, ruser.CEEA_JOBCODE_DESCR, ruser.USER_TYPE, ruser.MAIN_TYPE, ruser.CEEA_PO_AGENT_NUMBER, ruser.CEEA_PO_AGENT_NAME, ruser.IS_CONFIRM, ruser.CREATED_ID, ruser.CREATED_BY, ruser.CREATION_DATE, ruser.CREATED_BY_IP, ruser.CREATED_FULL_NAME, ruser.LAST_UPDATED_ID, ruser.LAST_UPDATED_BY, ruser.LAST_UPDATE_DATE, ruser.LAST_UPDATED_BY_IP, ruser.LAST_UPDATED_FULL_NAME, ruser.VERSION, ruser.PASSWORD_END_DATE, ruser.SYN_IAM_STATUS, rbac_role.ROLE_ID, rbac_role.ROLE_CODE, rbac_role.ROLE_TYPE, role_user.START_DATE, role_user.END_DATE from scc_rbac_user ruser left join scc_rbac_role_user role_user on ruser.USER_ID=role_user.USER_ID left join scc_rbac_role rbac_role on role_user.ROLE_ID = rbac_role.ROLE_ID
and exists ( select 1 from scc_rbac_role_language role_language where role_language.role_id = rbac_role.role_id and role_language.ROLE_NAME like concat('%',#{roleName},'%') )
and ruser.COMPANY_ID = #{companyId}
and ruser.USER_ID = #{userId}
and ruser.USERNAME like concat('%',#{username},'%')
and ruser.NICKNAME like concat('%',#{nickname},'%')
and ruser.PHONE like concat('%',#{phone},'%')
and ruser.USER_TYPE = #{userType}
and ruser.START_DATE >= #{startDate}
and ruser.END_DATE <= #{endDate}
and rbac_role.ROLE_CODE = #{roleCode}
and rbac_role.ROLE_TYPE = #{roleType}
order by ruser.LAST_UPDATE_DATE
